/// <summary>
/// Extension of <c>CustConfirmJour</c> to trigger the sales order confirmed business event.
/// </summary>
[ExtensionOf(tableStr(CustConfirmJour))]
final class AAXCustConfirmJour_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the sales order confirmed business event when a confirmation journal is created.
/// </summary>
void insert()
{
    next insert();

    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXSalesOrderConfirmedBusinessEvent)))
    {
        AAXSalesOrderConfirmedBusinessEvent::newFromCustConfirmJour(this).send();
    }
}
